.card {
  width: 300px;
  padding: 20px;
  border: 4px solid #1d4ed8;
  margin: 24px;
  background-color: #eff6ff;   /* fills content and padding, not the margin */
}

/* content-box (default): 300 + 20 + 20 + 4 + 4 = 348px on screen */
.card {
  box-sizing: content-box;
  width: 300px;
  padding: 20px;
  border: 4px solid #1d4ed8;
}

/* border-box: the 300px includes padding and border; the content gets 252px */
.card {
  box-sizing: border-box;
  width: 300px;
  padding: 20px;
  border: 4px solid #1d4ed8;
}

.card {
  width: 20rem;
  margin: 2rem auto;      /* 2rem above and below, centred horizontally */
  padding: 1rem 1.5rem;   /* 1rem top and bottom, 1.5rem left and right */
  border: 1px solid #cbd5e1;
  border-radius: 8px;
}
